using EnqueueDisconnectErrorFn = void(*)(void*, void*);
static EnqueueDisconnectErrorFn OrigEnqueueDisconnectError = nullptr;

// [1.14.7 2026-10-04] This hook used to log only errorTextPresent, which lost the reason and the caller and
// made the client's disconnect unactionable. It now reads the validated FText safely (SafeFTextToString
// already bounds the read), records a bounded REDACTED reason plus the caller RVA, and forwards the pointer
// unchanged - the original keeps ownership, nothing is copied or destroyed here.
static std::string RedactForLog(const std::string& Text, size_t MaxLen) {
    std::string Out;
    Out.reserve(Text.size() < MaxLen ? Text.size() : MaxLen);
    size_t Run = 0;
    for (size_t i = 0; i < Text.size() && Out.size() < MaxLen; ++i) {
        const unsigned char C = static_cast<unsigned char>(Text[i]);
        const bool Tokenish = (C >= '0' && C <= '9') || (C >= 'a' && C <= 'z') || (C >= 'A' && C <= 'Z') || C == '-' || C == '_';
        if (Tokenish) {
            ++Run;
            if (Run > 24) {              // long unbroken token-like run: mask it
                if (Out.size() < 12 || Out.compare(Out.size() - 12, 12, "<redacted>") != 0) Out += "<redacted>";
                while (i + 1 < Text.size() && Out.size() < MaxLen) {
                    const unsigned char N = static_cast<unsigned char>(Text[i + 1]);
                    const bool NextTokenish = (N >= '0' && N <= '9') || (N >= 'a' && N <= 'z') || (N >= 'A' && N <= 'Z') || N == '-' || N == '_';
                    if (!NextTokenish) break;
                    ++i;
                }
                Run = 0;
                continue;
            }
        } else {
            Run = 0;
        }
        Out += static_cast<char>(C);
    }
    if (Text.size() > Out.size()) Out += "...";
    return Out;
}

static void HookEnqueueDisconnectError(void* Context, void* ErrorTextPtr) {
    const std::string Reason = RedactForLog(SafeFTextToString(ErrorTextPtr), 160);
    void* Caller = _ReturnAddress();
    const uintptr_t CallerRva = (Globals::BaseAddress && reinterpret_cast<uintptr_t>(Caller) >= Globals::BaseAddress)
        ? reinterpret_cast<uintptr_t>(Caller) - Globals::BaseAddress
        : 0;
    MpLog(std::string("[EnqueueDisconnectError] reason='") + Reason + "' callerRva=+0x"
        + MpHex(CallerRva) + " this=" + MpPtr(Context)
        + " (forwarded unchanged; original keeps ownership)");
    if (OrigEnqueueDisconnectError) {
        OrigEnqueueDisconnectError(Context, ErrorTextPtr);
    }
}

using EasyAntiCheatHandleErrorFn = uint64_t(*)(void*, void*);
static EasyAntiCheatHandleErrorFn OrigEasyAntiCheatHandleError = nullptr;

// [1.14.7 2026-10-04] The previous version of this hook suppressed EVERY EAC error unconditionally.
// It is replaced by the scoped version defined with the EAC block further down, which absorbs only the
// expected private-client initialisation failure and forwards everything else to the original.
// The typedef and OrigEasyAntiCheatHandleError above are kept for that hook.

// ============================================================================
// [1.14.7 EAC DIAGNOSIS + SCOPED ERROR HANDLING 2026-10-04]
//
// Verified in the 1.14.7 binary:
//   StartupModule       0x01474ED0  checks NoEAC via FUN_142634de0(cmdline, L"NoEAC") and also has the path
//                                   "EnableEasyAntiCheatFeatures is false, EAC client will not load"
//   client creation     0x01477DD0  produces the IGameClient creation error
//   FEasyAntiCheatClient::HandleError 0x01476F20
//       undefined8 FUN_141476f20(this, FString* message)
//       - if a game callback is bound (this+8, vtable +0x30 != 0) it DISPATCHES there: vtable +0x48
//       - otherwise it falls back to the native dialog: "EasyAntiCheat Error: %s"
//       So the return is 64-bit (undefined8), and the caller reads AL. The old uint64_t declaration was
//       therefore correct; EAC suppression stopped because commit e320e022 REMOVED the hooks, not because of
//       the type. This restores it narrowly.
//
// Scope: only the expected private-client initialisation failure is absorbed. Every other EAC error is
// forwarded to the original unchanged, so ordinary error reporting and Central Guard checks still run.
static std::atomic<int> g_eacSuppressedCount{ 0 };
static std::atomic<int> g_eacForwardedCount{ 0 };

// The flag booleans are declared with the command-line hooks above; this records whether we logged them.
static bool g_eacFlagsLogged = false;

static std::wstring ReadFStringSafe(const void* StringPtr, size_t MaxChars) {
    if (!StringPtr || !IsReadablePointer(const_cast<void*>(StringPtr), 0x10)) return std::wstring();
    const wchar_t* Data = *reinterpret_cast<const wchar_t* const*>(StringPtr);
    const int32_t Num = *reinterpret_cast<const int32_t*>(reinterpret_cast<uintptr_t>(StringPtr) + 0x08);
    if (!Data || Num <= 0) return std::wstring();
    const size_t Count = static_cast<size_t>(Num) > MaxChars ? MaxChars : static_cast<size_t>(Num);
    if (!IsReadablePointer(const_cast<wchar_t*>(Data), Count * sizeof(wchar_t))) return std::wstring();
    return std::wstring(Data, Count > 0 ? Count - 1 : 0);
}

static uint64_t HookEasyAntiCheatHandleError(void* thisPtr, void* ErrorMessagePtr) {
    const std::wstring Message = ReadFStringSafe(ErrorMessagePtr, 512);

    // The expected private-client initialisation failure: the game could not create its IGameClient.
    // Nothing else is absorbed.
    const bool IsExpectedClientInitFailure =
        Message.find(L"IGameClient") != std::wstring::npos ||
        Message.find(L"Failed to create") != std::wstring::npos;

    if (IsExpectedClientInitFailure) {
        const int Seq = g_eacSuppressedCount.fetch_add(1, std::memory_order_relaxed);
        if (Seq < 4) {
            MpLog("[EACPopup] absorbed expected client-init failure (len=" + std::to_string(Message.size())
                + " chars, contains IGameClient=" + std::to_string(Message.find(L"IGameClient") != std::wstring::npos ? 1 : 0)
                + ") this=" + MpPtr(thisPtr));
        }
        return 1;   // AL=1: handled, no dialog
    }

    const int Seq = g_eacForwardedCount.fetch_add(1, std::memory_order_relaxed);
    if (Seq < 4) {
        MpLog("[EACPopup] forwarding a non-client-init EAC error to the original (len="
            + std::to_string(Message.size()) + " chars) this=" + MpPtr(thisPtr));
    }
    return OrigEasyAntiCheatHandleError
        ? OrigEasyAntiCheatHandleError(thisPtr, ErrorMessagePtr)
        : 0;
}

static void LogEacStartupFlags(const char* Where) {
    if (g_eacFlagsLogged) return;
    g_eacFlagsLogged = true;
    const wchar_t* OsCmd = GetCommandLineW();
    const std::wstring OsLine = OsCmd ? std::wstring(OsCmd) : std::wstring();
    const bool OsNoEAC = OsLine.find(L"-NoEAC") != std::wstring::npos;
    MpLog(std::string("[EACFlags] ") + Where
        + " os_NoEAC=" + std::to_string(OsNoEAC ? 1 : 0)
        + " engine_FCommandLine_NoEAC=" + std::to_string(g_engineCmdLineSawNoEAC ? 1 : 0)
        + " os_DisableEOS=" + std::to_string(OsLine.find(L"-DisableEOS") != std::wstring::npos ? 1 : 0)
        + " engine_FCommandLine_DisableEOS=" + std::to_string(g_engineCmdLineSawDisableEOS ? 1 : 0)
        + " (booleans only; no raw arguments recorded)");
}

