float TotalNoPlayersTime = 0.0f;

bool EnableWatchdog = true;

void* OrigGameEngineTick = nullptr;
void* OrigInteractionCalloutHideHoldText = nullptr;
void* OrigArchonLoadingScreenFadeIn = nullptr;

static bool SanitizeNetDriverClientConnections(void* NetDriver, const char* Tag);

// [CollectionFix] The GameNetDriver is registered into the world's gameplay FLevelCollections (the engine's source of truth that
// UWorld::SetActiveLevelCollection copies into UWorld->NetDriver). Unconditional — no flag, no legacy poke.

// Per-tick idempotent registration guard (validation build; production repair moves this to the driver/world
// init point once proven stable). Registers Networking::NetDriver into the gameplay FLevelCollections
// (type 0 DynSource + type 2 Static; never demo/replay). Self-protecting: RESOLVES BY NAME FIRST and only writes
// the collection fields if the WorldContext resolver returns our driver (so SetActiveLevelCollection's re-resolve
// cannot re-null it). Never pokes World->NetDriver. Logs deferred/rejected states once per world for visibility.
static void* g_regWorld = nullptr;
static void* g_deferredWorld = nullptr;
static void* g_rejectedWorld = nullptr;
static bool RegisterNetDriverInLevelCollections() {
    if (!Globals::Listening || !Networking::NetDriver || !IsReadablePointer(Networking::NetDriver, 0x198)) return false;
    UWorld* w = UWorld::GetWorld();
    if (!w || !IsReadablePointer(w, 0x160)) return false;
    if (g_regWorld == reinterpret_cast<void*>(w)) return true;   // already registered for this world (fast path)

    void* drvWorld = *reinterpret_cast<void**>(reinterpret_cast<uintptr_t>(Networking::NetDriver) + 0x140);  // UNetDriver::World
    uintptr_t arr = *reinterpret_cast<uintptr_t*>(reinterpret_cast<uintptr_t>(w) + 0x148);
    int32_t count = *reinterpret_cast<int32_t*>(reinterpret_cast<uintptr_t>(w) + 0x150);
    bool collectionsOk = (arr && count > 0 && count <= 8 && IsReadablePointer(reinterpret_cast<void*>(arr), static_cast<size_t>(count) * 0x78));
    // Deferred: driver not yet bound to this world, or collections not ready (e.g. mid-travel). Do NOT poke World->NetDriver.
    if (drvWorld != reinterpret_cast<void*>(w) || !collectionsOk) {
        if (g_deferredWorld != reinterpret_cast<void*>(w)) {
            g_deferredWorld = reinterpret_cast<void*>(w);
            MpLog("[CollectionFix] registration deferred: world=" + MpPtr(w) + " driverWorld=" + MpPtr(drvWorld)
                + " collections=" + (collectionsOk ? ("n=" + std::to_string(count)) : std::string("unavailable")));
        }
        return false;
    }
    // RESOLVE FIRST (self-protect): the WorldContext by-name resolver must return our driver before touching any field.
    void* gengine = IsReadablePointer(reinterpret_cast<void*>(Globals::BaseAddress + 0x06FC3CE8), 8)
        ? *reinterpret_cast<void**>(Globals::BaseAddress + 0x06FC3CE8) : nullptr;
    uint64_t nm = *reinterpret_cast<uint64_t*>(reinterpret_cast<uintptr_t>(Networking::NetDriver) + 0x190);  // NetDriverName
    // [1.14.7 ROOT-CAUSE FIX 2026-10-04] This called the WRONG overload: RVA 0x04266770 is the
    // PendingNetGame lookup (it compares the context field at +0x1A0, which the SDK documents as
    // PendingNetGame), while the argument here is a UWorld. The UWorld overload is RVA 0x042667F0 - it
    // compares context+0x280, the same FWorldContext::World offset ResolveWorldContextFromWorld uses in
    // reverse. Because the wrong overload never matched, the lookup returned null, registration was refused
    // ("registration REJECTED (driver not in WorldContext; would re-null) ... byNameResolve=null"), the level
    // collections were never populated, and UWorld::SetActiveLevelCollection (RVA 0x042D9740) then copied a
    // null driver into World->NetDriver - overwriting the one-time assignment Networking::Listen makes.
    //
    // That null is the dispatch fault: the native caller loads the world's network-notify interface from
    // NetDriver+0x208, and that interface lives at UWorld+0x28, so its +0x10 field IS UWorld::NetDriver
    // (UWorld+0x38). Measured: rcx=0x23437DF19F8 and rcx-0x28=0x23437DF19D0, which is exactly the world
    // address the runtime had logged. So the fault was never a destroyed UObject - it was a null world driver.
    void* reResolve = (gengine && IsReadablePointer(gengine, 0xC48))
        ? reinterpret_cast<void* (*)(void*, void*, uint64_t)>(Globals::BaseAddress + 0x042667F0)(gengine, w, nm) : nullptr;
    if (reResolve != reinterpret_cast<void*>(Networking::NetDriver)) {
        if (g_rejectedWorld != reinterpret_cast<void*>(w)) {
            g_rejectedWorld = reinterpret_cast<void*>(w);
            MpLog("[CollectionFix] registration REJECTED (driver not in WorldContext; would re-null): world=" + MpPtr(w)
                + " byNameResolve=" + MpPtr(reResolve) + " driver=" + MpPtr(Networking::NetDriver) + " — NOT writing collections");
        }
        return false;   // retry next tick; if this persists, context registration is required before the collection write
    }
    // Verified -> safe to write the collection source-of-truth.
    int populated = 0;
    for (int i = 0; i < count; ++i) {
        uintptr_t c = arr + static_cast<uintptr_t>(i) * 0x78;
        uint8_t type = *reinterpret_cast<uint8_t*>(c + 0x00);
        if (type == 0 || type == 2) {   // DynSource + Static gameplay collections only
            *reinterpret_cast<void**>(c + 0x10) = reinterpret_cast<void*>(Networking::NetDriver);  // FLevelCollection::NetDriver
            ++populated;
        }
    }
    g_regWorld = reinterpret_cast<void*>(w);
    MpLog("[CollectionFix] set driver on " + std::to_string(populated) + " gameplay collection(s) world=" + MpPtr(w)
        + " driver=" + MpPtr(Networking::NetDriver) + " byNameResolve=" + MpPtr(reResolve) + " resolveMatches=Y");
    return true;
}

static void SanitizeNetDriverBeforeEngineTick() {
    if (!Globals::Listening || !Networking::NetDriver || !IsReadablePointer(Networking::NetDriver, 0x2B0)) {
        return;
    }

    UWorld* World = UWorld::GetWorld();
    if (!World || !IsReadablePointer(World, 0x40)) {
        return;
    }

    static FName GameNetDriverName = FName();
    static bool GameNetDriverNameInit = false;

    if (!GameNetDriverNameInit) {
        GameNetDriverName = UKismetStringLibrary::Conv_StringToName(L"GameNetDriver");
        GameNetDriverNameInit = true;
    }

    // Register the GameNetDriver into the gameplay FLevelCollections (the source UWorld::SetActiveLevelCollection
    // copies into UWorld->NetDriver); the engine then propagates it. Idempotent per world; we never poke
    // World->NetDriver directly. This is the ONLY supported path (no COLLECTION_FIX flag, no legacy fallback).
    RegisterNetDriverInLevelCollections();
    Networking::NetDriver->World = World;
    Networking::NetDriver->NetDriverName = GameNetDriverName;
    Networking::NetDriver->ServerConnection = nullptr;
}

// [Group D cleanup 2026-07-13] SnapWorldDriver ([WorldDriverTransition] stage monitor) removed —
// read-only diagnostic that localized the driver-null transition; root fixed by the collection registration (item 2).

static bool NativeNetTick();  // [fwd] NATIVE_NET_TICK.flag A/B — defined below; gates the manual dispatch/flush

// A native net-tick exception can become persistent once a connection enters a bad teardown state.
// Logging it every engine frame creates megabytes of I/O and can itself stall the game thread. Preserve
// the first failure, emit one aggregate every 30 seconds, and report recovery once. The SEH filters still
// retain the bounded exception record/stack evidence used for root-cause analysis.
struct ManualNetTickFailureState {
    bool Active = false;
    uint64_t LastReportMs = 0;
    uint64_t FailuresSinceReport = 0;
};

static ManualNetTickFailureState g_TickDispatchFailureState;
static ManualNetTickFailureState g_TickFlushFailureState;

static void ReportManualNetTickFailure(bool IsFlush, uint64_t Tick) {
    ManualNetTickFailureState& State = IsFlush ? g_TickFlushFailureState : g_TickDispatchFailureState;
    const char* Phase = IsFlush ? "TickFlush" : "TickDispatch";
    const uint64_t NowMs = GetTickCount64();
    ++State.FailuresSinceReport;

    if (!State.Active) {
        State.Active = true;
        State.LastReportMs = NowMs;
        MpLog("[NetTickFault] " + std::string(Phase) + " first exception at tick=" + std::to_string(Tick)
            + "; repeated failures will be summarized every 30s");
        State.FailuresSinceReport = 0;
        return;
    }

    if (NowMs - State.LastReportMs >= 30000) {
        MpLog("[NetTickFault] " + std::string(Phase) + " still failing at tick=" + std::to_string(Tick)
            + " failuresSinceLast=" + std::to_string(State.FailuresSinceReport));
        State.LastReportMs = NowMs;
        State.FailuresSinceReport = 0;
    }
}

static void ReportManualNetTickRecovery(bool IsFlush, uint64_t Tick) {
    ManualNetTickFailureState& State = IsFlush ? g_TickFlushFailureState : g_TickDispatchFailureState;
    if (!State.Active) return;

    const char* Phase = IsFlush ? "TickFlush" : "TickDispatch";
    MpLog("[NetTickFault] " + std::string(Phase) + " recovered at tick=" + std::to_string(Tick)
        + " unreportedFailures=" + std::to_string(State.FailuresSinceReport));
    State = {};
}

static int TickDispatchExceptionFilter(unsigned int Code, EXCEPTION_POINTERS* ExceptionInfo) {
    if (ExceptionInfo && IsReadablePointer(ExceptionInfo, sizeof(EXCEPTION_POINTERS)) &&
        IsReadablePointer(ExceptionInfo->ExceptionRecord, sizeof(EXCEPTION_RECORD))) {
        LogExceptionRecord(
            "ManualTickDispatchSEH",
            ExceptionInfo->ExceptionRecord,
            IsReadablePointer(ExceptionInfo->ContextRecord, sizeof(CONTEXT)) ? ExceptionInfo->ContextRecord : nullptr);
    }
    else {
        EXCEPTION_RECORD Record{};
        Record.ExceptionCode = Code;
        Record.ExceptionAddress = _ReturnAddress();
        LogExceptionRecord("ManualTickDispatchSEH", &Record, nullptr);
    }

    return EXCEPTION_EXECUTE_HANDLER;
}

// [1.14.7 FIX] The UGameEngine captured by GameEngineTickHook; the manual tick needs it as its first
// argument (see the note at the hook definition). Declared here because this function is defined earlier.
static void* g_GameEnginePtr = nullptr;

// [1.14.7 FIX 2026-10-04] Reentrancy guard. The manual dispatch drives the world/net path, which can route
// back into this same function (the engine tick path re-enters the net tick). Without a guard that recursion
// is unbounded, and the observed failure is exactly a stack-exhaustion signature rather than a bad pointer:
//   ManualTickDispatchSEH code=0xC0000005 address=ucrtbase.dll+0xD8AE params=0x0,0xFFFFFFFFFFFFFFFF
// and the bytes at that address are
//   66 0F 7F 85 F0 03 00 00   movdqa [rbp+0x3F0], xmm0
// i.e. a CRT routine writing a large stack frame and faulting on the frame itself. (The earlier [0+0x88]
// fault at 0x42CE8B6 is gone - the multi-world UWorld::NetDriver poke fixed it, guardSkips stayed 0.)
// Re-entering is never useful here, so the nested call simply returns.
static thread_local int s_manualTickDepth = 0;

// Set while the manual dispatch is running, so a re-entrant tick cannot recurse (see the call site in
// GameEngineTickHook). The guard lives there because this function uses __try, which forbids objects
// requiring unwinding.
static thread_local bool s_inManualTick = false;

static bool SafeManualTickDispatch(UNetDriver* NetDriver, float DeltaTime) {
    // [NATIVE_NET_TICK A/B] skip the manual (double) drive — native engine tick owns TickDispatch.
    // (No logging here: this function uses __try, which forbids objects requiring unwinding. The
    //  one-time mode banner is emitted from NativeNetTick()'s cache init instead.)
    if (NativeNetTick()) return true;
    using TickDispatchFn = void(*)(UNetDriver*, float);

    // [1.14.7 2026-10-04] REVERTED: passing the UGameEngine as the first argument is WRONG. Measured with
    // the engine pointer captured from GameEngineTickHook and used here:
    //   ManualTickDispatchSEH code=0xC0000005 address=exe+0x39F9A70 params=0x0,0x500000015
    //   [NetTickFault] TickDispatch first exception at tick=2
    //   recvfrom: 0  sendto: 0  fatal=1   (the hub crash-looped, one restart per minute)
    // i.e. it faults immediately and does not even read the socket, whereas passing the NetDriver reads it
    // (recvfrom <- 127.0.0.1:52155 len=29) before faulting at [0+0x88]. So NetDriver IS the correct first
    // argument and the [0+0x88] fault is a separate, still-open defect. No logging here - this function uses
    // __try, which forbids objects requiring unwinding (see the note above).
    void* TickTarget = reinterpret_cast<void*>(NetDriver);

    __try {
        // [1.14.7 2026-10-04] I changed this to 0x03FAE420 (FUN_143fae420, the address hooked as
        // NetDriverTickDispatchInner) on the theory that 0x00A82CF0 was a stale 1.12 RVA. That was WRONG and
        // the measurements say so:
        //   with 0x00A82CF0 : hub reads  -> "recvfrom <- 127.0.0.1:52155 len=29"  (then faults, see below)
        //   with 0x03FAE420 : hub reads  -> nothing at all (recvfrom: 0, SEH faults: 0)
        // So 0x00A82CF0 IS the working dispatch entry and it is restored here. The real defect is that the
        // dispatch then faults at exe+0x42CE8C1 with 0xC0000005, which the SEH filter absorbs
        // ("[ManualTickDispatchSEH] code=0xC0000005", "[NetTickFault] TickDispatch recovered at tick=N").
        // That fault - not the address - is what the earlier double-drive A/B recorded as "NetDriver
        // corruption", and it is the remaining blocker for the travel handshake.
        reinterpret_cast<void(*)(void*, float)>(Globals::BaseAddress + 0x00A82CF0)(TickTarget, DeltaTime);
        return true;
    }
    __except (TickDispatchExceptionFilter(GetExceptionCode(), GetExceptionInformation())) {
        return false;
    }
}

// [1.12.0] UNetDriver::TickFlush at RVA 0x03D91DC0. Send-side counterpart to TickDispatch.
// Confirmed via Ghidra decompile of FUN_143d91dc0 (vtable slot right after TickDispatch and
// PostTickDispatch on UIpNetDriver's vtable at 0x144E0AF98):
//   - Same signature as TickDispatch: void __fastcall(UNetDriver* this, float DeltaSeconds)
//   - Walks ClientConnections at this[0x12] (Num at [0x13])
//   - Calls UNetConnection::Tick(DeltaSeconds) on each (vtable slot +0x2C8)
//   - Invokes ServerReplicateActors via this[0x21] (World) and driver vtable +0x2A8
//   - Manipulates per-connection bytes-sent stats at conn+0x4C4..+0x4D0 (only meaningful
//     on the send path). This is the flush that emits queued replication + ACKs.
//
// Why we call it here: our custom net-tick path in GameEngineTickHook calls TickDispatch
// (receive) but nothing was calling TickFlush (send). That's why the server sees InSeq
// climbing but NextOutGoingSeq frozen; NMT_Welcome, pawn replication, and the "clear the
// loading screen" chain sit queued and never leave the box.
static int TickFlushExceptionFilter(unsigned int Code, EXCEPTION_POINTERS* ExceptionInfo) {
    if (ExceptionInfo && IsReadablePointer(ExceptionInfo, sizeof(EXCEPTION_POINTERS)) &&
        IsReadablePointer(ExceptionInfo->ExceptionRecord, sizeof(EXCEPTION_RECORD))) {
        LogExceptionRecord(
            "ManualTickFlushSEH",
            ExceptionInfo->ExceptionRecord,
            IsReadablePointer(ExceptionInfo->ContextRecord, sizeof(CONTEXT)) ? ExceptionInfo->ContextRecord : nullptr);
    }
    else {
        EXCEPTION_RECORD Record{};
        Record.ExceptionCode = Code;
        Record.ExceptionAddress = _ReturnAddress();
        LogExceptionRecord("ManualTickFlushSEH", &Record, nullptr);
    }
    return EXCEPTION_EXECUTE_HANDLER;
}

static bool SafeManualTickFlush(UNetDriver* NetDriver, float DeltaTime) {
    // [NATIVE_NET_TICK A/B] skip the manual (double) drive — native engine tick owns TickFlush -> ServerReplicateActors.
    if (NativeNetTick()) return true;
    using TickFlushFn = void(*)(UNetDriver*, float);

    __try {
        reinterpret_cast<TickFlushFn>(Globals::BaseAddress + 0x03FAE700)(NetDriver, DeltaTime);
        return true;
    }
    __except (TickFlushExceptionFilter(GetExceptionCode(), GetExceptionInformation())) {
        return false;
    }
}

// [2026-07-18 double-drive A/B] NATIVE_NET_TICK.flag — the network path is currently driven TWICE per
// frame: the native UGameEngine::Tick (OrigGameEngineTick) drives UWorld::Tick -> UNetDriver::TickDispatch/
// TickFlush now that the NetDriver is registered in the world/level collections, AND the DLL calls
// SafeManualTickDispatch + SafeManualTickFlush again immediately afterward. Both funnel through the hooked
// vtable slot +0x2A8 (ServerReplicateActorsHook, ArchonDirect), so ServerReplicateActors runs ~2x per frame
// -> the [SRA enter] log shows ~60Hz while NetServerMaxTickRate=30. Double-driving the graph during rapidly
// changing actor state (travel / possession / disconnect) is the strongest remaining desync/lifecycle
// suspect (ServerMove TimeStamp expired, stretched proxies, higher churn-failure probability).
//
// When this flag is present next to the game .exe, the manual TickDispatch + TickFlush are SKIPPED, leaving
// the native engine tick as the SOLE driver -> the graph is invoked ONCE per network frame (expected
// [SRA enter] ~30Hz). CONFIRMATION SIGNAL: enable REPGRAPH_DIAG.flag too and watch [SRA enter] SRA=..Hz:
//   ~30Hz  => native tick drives the net driver; manual calls were redundant (KEEP this on, promote later).
//   ~0Hz / no [SRA enter] => native tick does NOT drive TickFlush here; manual calls were load-bearing
//                            -> remove the flag (replication is broken in this mode).
// Default OFF (absent flag = current double-drive behaviour). Opt-in + reversible: deploying the DLL alone
// changes nothing until the flag is dropped and the server restarted. Read once (cached) — set before launch.
/*
 * [2026-07-19] MANUAL_TICK_ZERO_DT.flag — *** BROKEN. DO NOT ENABLE. ***
 *
 * TESTED AND FAILED: with this flag the server becomes unjoinable. Verified A/B on port 8790:
 *     WITH    (22:58, pid 1308): connCount -2 -> 0 at startup, then NOTHING. No client ever connects.
 *     WITHOUT (23:02, pid 4284): connCount 0 -> 1 @ 23:03:10, PostLoginPE#0 @ 23:03:12. Joins fine.
 *
 * WHY: UNetDriver::TickDispatch(DeltaSeconds) does not merely accumulate a clock — it drives
 * UNetConnection::Tick(DeltaSeconds), which runs the connection handshake state machine and its
 * timers. DeltaTime=0 freezes those timers, so the handshake never completes. The parameter is
 * load-bearing for connection progression, not just timekeeping.
 *
 * The surgical replacement (NOT yet implemented) is to let TickDispatch run with the REAL DeltaTime
 * and instead save/restore UNetDriver::Time (+0x210) around the manual call, removing only the double
 * clock advance. DO NOT build that until the underlying assumption is confirmed in Ghidra: that this
 * build's TickDispatch actually accumulates Time from DeltaSeconds. Two flags have now been shipped on
 * unverified assumptions (NATIVE_NET_TICK, this one) and both broke joining.
 *
 * Original rationale retained below for context.
 *
 * [2026-07-19] MANUAL_TICK_ZERO_DT.flag — beam/orbit visual desync A/B.
 *
 * BACKGROUND: NATIVE_NET_TICK.flag was the intended A/B for the double-drive, but it was tried and the
 * server became unjoinable — i.e. the documented "~0Hz / no [SRA enter] => manual calls were load-bearing"
 * branch. The native engine tick does NOT drive TickFlush on this setup, so the manual calls cannot simply
 * be removed. That flag is therefore a dead end for this investigation and must NOT be promoted.
 *
 * SYMPTOM THIS TARGETS: some behemoth abilities render wrong — Valomyr's orbiting orbs fire beams that
 * start from displaced positions, clip into terrain, or draw only partially. Gameplay/damage is correct.
 * Critically it is SELECTIVE: only some abilities on some behemoths. A globally corrupted replication
 * path would degrade everything equally, so a global explanation does not fit.
 *
 * MECHANISM: the affected visuals are the ones derived from ELAPSED TIME rather than from a replicated
 * transform:
 *     UOrbitingProjectileComponent : float SpawnTime, float NormalizedElapsedTime
 *                                    GetNormalizedTimeElapsed(), UpdateParticlePosition_Native(...)
 *     UProjectileBehavior_BeamBase : FVector StartPos / OwnerPos / CurrentEndPoint  (computed locally)
 * The orb's orbit phase comes from elapsed time; the beam's origin is inherited from the orb. Montage
 * melee, simple projectiles and AoEs do not integrate elapsed time client-side — and those look fine.
 *
 * UNetDriver::TickDispatch(DeltaSeconds) advances the driver's ElapsedTime (the network clock used for
 * client/server time sync). The manual call passes the SAME DeltaTime the native tick already consumed:
 *     SafeManualTickDispatch(NetDriver, DeltaTime);   // second time, same value
 * so that clock plausibly runs at ~2x real time, and anything phase-derived resolves to the wrong point.
 *
 * WHAT THIS FLAG DOES: passes 0.0f as DeltaTime to the MANUAL TickDispatch only. The call still happens,
 * so replication keeps running and the server stays joinable — unlike NATIVE_NET_TICK.flag. Only the
 * double clock advance is removed. TickFlush keeps its real DeltaTime because it drives bandwidth/
 * throttling, not the clock.
 *
 * *** UNVERIFIED ASSUMPTION: that this build's TickDispatch accumulates ElapsedTime from DeltaSeconds.
 * That is standard UE behaviour and matches the symptom, but it has NOT been confirmed in Ghidra for this
 * binary. If this flag changes nothing, verify that before pursuing the time-base theory further. ***
 *
 * Default OFF. Read once, cached — set before launch.
 */
static bool ManualTickZeroDeltaTime() {
    static int c = -1;
    if (c < 0) {
        c = MpExeRelativeFlagPresent(L"MANUAL_TICK_ZERO_DT.flag") ? 1 : 0;
        MpLog(std::string("[ManualTickDT] MANUAL_TICK_ZERO_DT.flag ")
            + (c ? "PRESENT -> *** BROKEN: server will be UNJOINABLE (handshake timers frozen). REMOVE THIS FLAG. *** "
                   "Replication still runs; server stays joinable. Watch whether orbit/beam visuals correct "
                   "themselves while everything else is unchanged."
                 : "absent -> manual TickDispatch gets the real DeltaTime (default; clock may double-advance)."));
    }
    return c == 1;
}

/*
 * [2026-07-19] MANUAL_TICK_HALF_RATE.flag — rate-parity A/B (alternative to the clock fix above).
 *
 * Runs the manual TickDispatch/TickFlush pair on every OTHER engine frame, so ServerReplicateActors is
 * invoked about once per network frame (~30Hz, matching NetServerMaxTickRate) instead of ~60Hz.
 *
 * This is a DIFFERENT hypothesis from MANUAL_TICK_ZERO_DT: it assumes the problem is replication
 * FREQUENCY rather than the clock. Note the cost — halving the manual drive also halves the effective
 * player-pawn replication rate, which works against the deliberate PlayerRepBoost smoothness fix. Prefer
 * the zero-DT flag first; use this only to test the frequency theory.
 *
 * Do NOT enable both at once — you would not know which one moved the needle.
 * Default OFF.
 */
static bool ManualTickHalfRate() {
    static int c = -1;
    if (c < 0) {
        c = MpExeRelativeFlagPresent(L"MANUAL_TICK_HALF_RATE.flag") ? 1 : 0;
        MpLog(std::string("[ManualTickRate] MANUAL_TICK_HALF_RATE.flag ")
            + (c ? "PRESENT -> manual TickDispatch/TickFlush run every OTHER frame (~30Hz SRA, matches "
                   "NetServerMaxTickRate). NOTE: also halves player-pawn replication rate."
                 : "absent -> manual drive runs every frame (default)."));
    }
    return c == 1;
}

static bool NativeNetTick() {
    static int c = -1;
    if (c < 0) {
        // [1.14.7 ROOT FIX 2026-10-03] Default is now NATIVE-ONLY (manual drive skipped).
        //
        // Ghidra: FUN_143fae420 is UNetDriver::TickDispatch (its own "Very long time between
        // ticks" string) and FUN_143fae700 is UNetDriver::TickFlush (it dispatches vtable
        // +0x2A8, ServerReplicateActors). GameEngineTickHook still calls the engine tick
        // (OrigGameEngineTick), which already drives UWorld::Tick -> TickDispatch/TickFlush,
        // so the manual path in this file drove the network path TWICE per frame.
        //
        // Controlled A/B on this machine (same build, same maps, only this flag differed):
        //   double drive ENABLED : both hubs logged "resetting invalid ClientConnections" and
        //                          "resetting invalid cleanup array" ~60-90s in, then died
        //                          (Ramsgate exit 3 after "Fatal error ... RemoveFromHash
        //                          NumRemoved = 0"; Training exit 0xC0000005).
        //   double drive DISABLED: both hubs stayed alive past 3 minutes with zero corruption
        //                          events and no fatal.
        // UNetDriver is byte-identical between the 1.12.0 and 1.14.7 SDK dumps and this
        // corruption never appears in the archived 1.12-era logs, so this is a 1.14.7-specific
        // regression caused by driving the net path twice.
        //
        // NATIVE_NET_TICK.flag (legacy) and MANUAL_NET_TICK.flag (new) are both honoured:
        // native-only is the default; MANUAL_NET_TICK.flag re-enables the legacy double drive
        // for A/B only and logs loudly.
        const bool LegacyNativeFlag = MpExeRelativeFlagPresent(L"NATIVE_NET_TICK.flag");
        const bool ManualOverride = MpExeRelativeFlagPresent(L"MANUAL_NET_TICK.flag");
        // [1.14.7 FIX 2026-10-04] Default flipped back to the MANUAL drive. The native-only default rested on
        // "the NetDriver is registered in the world/level collections, so the engine tick drives it", but this
        // build proves otherwise:
        //   [CollectionFix] registration REJECTED (driver not in WorldContext; would re-null)
        // so the engine never dispatches our named driver. With the manual path skipped NOTHING ticked it and
        // its socket was never read - measured with the socket diagnostics:
        //   client: sendto -> 127.0.0.1:8790 len=29   (once a second for the whole 20s window)
        //   hub:    zero recvfrom / WSARecvFrom / WSARecv calls
        // Enabling the manual drive made the hub read immediately: recvfrom <- 127.0.0.1:52155 len=29.
        // The crashes the earlier A/B blamed on double-driving were the stale TickDispatch RVA (0x00A82CF0),
        // now corrected to the verified 0x03FAE420 - not the double drive itself.
        // NATIVE_NET_TICK.flag still forces the old native-only behaviour for A/B.
        c = (LegacyNativeFlag || ManualOverride) ? 1 : 0;

        // [1.14.7 ROLE GATE 2026-10-04] The manual drive is for the MANAGED HUBS ONLY.
        //
        // Why it is needed there: the hub's named driver is not in the world context
        // ("[CollectionFix] registration REJECTED (driver not in WorldContext; would re-null)"), so the engine
        // never dispatches it and its socket is never read - measured: the client sent
        // "sendto -> 127.0.0.1:8790 len=29" once a second for 20s while the hub made zero receive calls.
        //
        // Why the CLIENT must not have it: a game client's driver IS engine-registered and IS ticked by the
        // engine, so driving it again would double-tick it. When the manual drive was enabled for both roles,
        // the client stopped reaching matchmaking entirely - it parked on the main menu with
        // OnPlayScreenPollTimer repeating and the backend saw no /candidate/join at all, where before it
        // travelled a few seconds after press-to-start.
        //
        // So: server role -> manual drive (unless NATIVE_NET_TICK.flag); client role -> always native.
        if (!Globals::AmServer) {
            c = 1;
        }

        // [1.14.7 FIX 2026-10-04] Native-only for the SERVER too, now that Networking::Listen points
        // UWorld::NetDriver (+0x38) at our named driver. The engine tick therefore dispatches OUR driver
        // exactly once, so the manual drive is no longer needed - and removing it also removes the null+0x88
        // fault it caused (a second engine tick per frame running in a state the first one never created:
        // "[ManualTickDispatchSEH] code=0xC0000005 ... params=0x0,0x88 regs{rax=0x0}").
        // NATIVE_NET_TICK.flag / MANUAL_NET_TICK.flag still override either way for A/B.
        // [1.14.7 2026-10-04] Round-20 forced native here on the theory that pointing UWorld::NetDriver at
        // our driver would make the engine tick dispatch it. Measured since: the engine NEVER calls
        // TickDispatch on it (instrumented counter: "TickDispatchInner call lines: 0"), so the server needs
        // the manual drive after all - now with the real UGameEngine as its first argument instead of the
        // net driver, which is what removes the [0+0x88] fault.
        // [2026-10-08] The message now reports the real reason. The old DISABLED text claimed
        // "MANUAL_NET_TICK.flag present ... expect NetDriver corruption" on every hub boot, although the
        // manual hub drive is the intended server default and no flag was installed.
        std::string Reason;
        if (!Globals::AmServer) {
            Reason = "ACTIVE: client role, the engine ticks its own registered driver.";
        } else if (c) {
            Reason = std::string("ACTIVE (A/B override: ")
                + (LegacyNativeFlag ? "NATIVE_NET_TICK.flag" : "MANUAL_NET_TICK.flag")
                + " present): manual TickDispatch/TickFlush SKIPPED on the server.";
        } else {
            Reason = "OFF (server default): the hub's named driver is not engine-registered, so the module "
                     "drives TickDispatch/TickFlush manually.";
        }
        MpLog("[NativeNetTick] native-only net tick " + Reason);
    }
    return c == 1;
}

