// FUN_141A60BC0 is the generic IArchonLoadingInterface dispatcher, not a controller-specific
// readiness getter. Ghidra verifies that it calls the interface vtable (+0x20) and reflected
// HasFinishedLoading implementation for every participating object. The SDK contains world/visual
// participants (escalation GameState, arrival cinematic trigger, armour, weapons and lanterns), so
// changing every false result to true can release the loading screen while streamed materials and
// sublevels are still initializing. On clients, allow the compatibility override only for the exact
// local AArchonPlayerController whose missing backend callback blocks player start.
static bool IsLocalArchonControllerReadinessObject(UObject* Object) {
    if (Globals::AmServer || !Object) return false;
    __try {
        if (!IsReadablePointer(Object, 0x2A0)
            || !IsRegisteredLiveObject(Object)
            || !Object->IsA(SDK::AArchonPlayerController::StaticClass())) {
            return false;
        }

        // SDK 1.12: APlayerController::Player @ +0x298; UPlayer::PlayerController @ +0x30.
        void* Player = *reinterpret_cast<void**>(reinterpret_cast<uintptr_t>(Object) + 0x298);
        if (!Player || !IsReadablePointer(Player, 0x38)
            || !IsRegisteredLiveObject(Player)
            || !reinterpret_cast<UObject*>(Player)->IsA(SDK::ULocalPlayer::StaticClass())) {
            return false;
        }

        void* PlayerController = *reinterpret_cast<void**>(
            reinterpret_cast<uintptr_t>(Player) + 0x30);
        if (PlayerController != Object || Object != s_LastPossessedPC) {
            return false;
        }

        // The controller override itself must obey the same travel-settle and stable-chain proof as
        // input/cinematic repair. Otherwise the hook could still close the loading screen before the
        // new map's possession graph has converged, even though non-controller blockers are natural.
        UObject* StablePawn = nullptr;
        return IsClientRolePumpPossessionStable(Object, &StablePawn);
    }
    __except (EXCEPTION_EXECUTE_HANDLER) {
        return false;
    }
}

bool HasFinishedLoadingHook(UObject* a1) {
    const bool Ret = reinterpret_cast<bool(*)(UObject*)>(OrigHasFinishedLoading)(a1);
    if (Ret) return true;

    const uintptr_t ReturnAddress = reinterpret_cast<uintptr_t>(_ReturnAddress());
    const uintptr_t CallerRva = ReturnAddress >= Globals::BaseAddress
        ? ReturnAddress - Globals::BaseAddress : 0;

    if (DiagNaturalMode()) {
        static std::atomic<int> s_hflNatural{ 0 };
        if (s_hflNatural.fetch_add(1, std::memory_order_relaxed) < 20) {
            MpLog(std::string("[ReadinessCompat] PRESERVE_FALSE mode=natural obj=")
                + (a1 ? a1->GetFullName() : "(null)")
                + " caller=+" + MpHex(CallerRva));
        }
        return false;
    }

    if (Globals::AmServer) {
        // Preserve the established dedicated-server compatibility behavior. The visual-loading race
        // is client-only; narrowing server readiness in the same build would mix two independent
        // changes and risk reintroducing player-start timeouts on headless instances.
        static std::atomic<int> s_hflServer{ 0 };
        if (s_hflServer.fetch_add(1, std::memory_order_relaxed) < 20) {
            MpLog(std::string("[ReadinessCompat] FORCE_TRUE scope=server-legacy obj=")
                + (a1 ? a1->GetFullName() : "(null)")
                + " caller=+" + MpHex(CallerRva));
        }
        return true;
    }

    if (IsLocalArchonControllerReadinessObject(a1)) {
        static std::atomic<int> s_hflController{ 0 };
        if (s_hflController.fetch_add(1, std::memory_order_relaxed) < 20) {
            const uint64_t Elapsed = s_LastPossessedAtMs != 0
                ? GetTickCount64() - s_LastPossessedAtMs : 0;
            MpLog(std::string("[ReadinessCompat] FORCE_TRUE scope=local-controller obj=")
                + a1->GetFullName()
                + " sinceClientRestartMs=" + std::to_string(Elapsed)
                + " caller=+" + MpHex(CallerRva));
        }
        return true;
    }

    // [1.14.7 DIAG 2026-10-08] Separate budgets: inventory item-id lookups (caller +0x1BFDF81,
    // FItemInstanceIdRepl::ResolveItemInstanceId) used up all 40 lines within 9 ms on the 8 Oct hunt
    // join, which would hide any later player-start blocker (caller +0x1C9BEB8, CheckForPlayerStartEvent).
    static std::atomic<int> s_hflPreserved{ 0 };
    static std::atomic<int> s_hflPreservedInventory{ 0 };
    std::atomic<int>& PreserveBudget = (CallerRva == 0x1BFDF81) ? s_hflPreservedInventory : s_hflPreserved;
    if (PreserveBudget.fetch_add(1, std::memory_order_relaxed) < 40) {
        MpLog(std::string("[ReadinessCompat] PRESERVE_FALSE scope=client-not-allowlisted obj=")
            + (a1 ? a1->GetFullName() : "(null)")
            + " caller=+" + MpHex(CallerRva));
    }
    return false;
}

