#include <fstream>

void* OrigProcessEventClient = nullptr;
void* OrigEasyAntiCheatErrorProc = nullptr;
void* OrigEasyAntiCheatStartup = nullptr;

// s_LastPossessedPC / s_LastPossessedAtMs / s_ArchonInputActivated now declared much earlier in
// this file (right before GameEngineTickHook), since its timeout fallback needs them too.

// [PROD] EAC popup suppression is permanent in the private-server build. The private setup
// intentionally ships without the native EasyAntiCheat interface, so EasyAntiCheatErrorProc
// only ever turns that expected init failure into a blocking modal — there is no legitimate
// case where we want the popup shown. Previously gated behind SUPPRESS_EAC_POPUP.flag; now
// unconditionally enabled (no flag required).
static bool SuppressEacPopupEnabled() {
    return true;
}

// Native exec for UArchonGameInstance::EasyAntiCheatErrorProc
// (Ghidra: 0x1420DC460, RVA 0x020DC460).  This is reached directly by the
// EAC startup path, before/without a UObject::ProcessEvent dispatch, which is
// why filtering ProcessEvent alone cannot suppress the modal dialog.
void EasyAntiCheatErrorProcHook(void* Context, void* Stack, void* Result) {
    (void)Context;
    (void)Stack;
    if (SuppressEacPopupEnabled()) {
        if (Result && IsReadablePointer(Result, 1)) {
            *reinterpret_cast<bool*>(Result) = false;
        }
        static bool Logged = false;
        if (!Logged) {
            Logged = true;
            MpLog("[EACPopup] suppressed native EasyAntiCheatErrorProc");
        }
        return;
    }
    if (OrigEasyAntiCheatErrorProc) {
        reinterpret_cast<void(*)(void*, void*, void*)>(OrigEasyAntiCheatErrorProc)(Context, Stack, Result);
    }
}

// FEasyAntiCheatClient::StartupModule (Ghidra 0x14136FE40, RVA 0x0136FE40).
// The popup is emitted from this startup path before ErrorProc is dispatched;
// skipping the module startup is equivalent to the game's -NoEAC branch.
void EasyAntiCheatStartupHook(void* Module) {
    if (SuppressEacPopupEnabled()) {
        (void)Module;
        static bool Logged = false;
        if (!Logged) {
            Logged = true;
            MpLog("[EACPopup] suppressed FEasyAntiCheatClient::StartupModule");
        }
        return;
    }
    if (OrigEasyAntiCheatStartup) {
        reinterpret_cast<void(*)(void*)>(OrigEasyAntiCheatStartup)(Module);
    }
}

