        MpLog("[PostLoginPE #" + std::to_string(Seq) + "] fn=" + FunctionName
            + " obj=" + MpPtr(Object) + "/" + ObjName + Extra);
        LogArchonLifecycle(("PostLoginPE#" + std::to_string(Seq)).c_str());
