// The body OWNS its by-value FText copy (the exec stub bumps the refcount for the copy; the body releases it at
// its tail), so every skip path releases it, exactly like the OnSetDisabled guard above. The pass-through path
// never touches it.
static void CwDisabledTextWhenEnabledDetour(void* W, const void* Text, float VerticalOffset, bool bMarkAsEnabled) {
    static std::atomic<uint64_t> s_skips{ 0 };
    if (!W) {
        ReleaseOwnedFTextParameter(Text);
        CwLogSkip(s_skips, "OnSetShowDisabledTextWhenEnabled", W, "this", {}, "skipped+ftext-released", 8, 1024);
        return;
    }
    const uintptr_t B = reinterpret_cast<uintptr_t>(W);
    const bool Bound = *reinterpret_cast<void**>(B + 0x3B0)
        && (!bMarkAsEnabled || (*reinterpret_cast<void**>(B + 0x3A8) && *reinterpret_cast<void**>(B + 0x3B8)));
    if (!Globals::AmServer || Bound) {
        OrigCwDisabledTextWhenEnabled(W, Text, VerticalOffset, bMarkAsEnabled);
        return;
    }
    ReleaseOwnedFTextParameter(Text);
    CwLogSkip(s_skips, "OnSetShowDisabledTextWhenEnabled", W, nullptr,
        { {0x3B0, "DisabledReason"}, {0x3A8, "InteractionHint"}, {0x3B8, "DisabledIcon"} }, "skipped+ftext-released", 8, 1024);
}

struct CwSite {
    const char* Name;
    uintptr_t Rva;
    const uint8_t* Expect;       // static storage (no initializer_list lifetime questions)
    size_t ExpectLen;
    uintptr_t SuperCallOffset;   // 0 = no parent call to verify
    uintptr_t SuperRva;
    void* Detour;
    void** Orig;
};

// Returns nullptr when the site is safe to hook, else a reason. Only reads .text.
static const char* CwVerifySite(const CwSite& S) {
    if (ResolveFunctionStartRva(S.Rva) != S.Rva) return "not-pdata-entry";
    const uint8_t* P = reinterpret_cast<const uint8_t*>(Globals::BaseAddress + S.Rva);
    const size_t Need = (std::max)(S.ExpectLen, static_cast<size_t>(S.SuperCallOffset + 5));
    if (!IsReadablePointer(const_cast<uint8_t*>(P), Need)) return "unreadable";
    if (memcmp(P, S.Expect, S.ExpectLen) != 0) return "prologue-mismatch";
    if (S.SuperCallOffset) {
        const uint8_t* C = P + S.SuperCallOffset;
        if (C[0] != 0xE8) return "super-mismatch";
        int32_t Rel = 0;
        memcpy(&Rel, C + 1, sizeof(Rel));
        const intptr_t Target = static_cast<intptr_t>(S.Rva + S.SuperCallOffset + 5) + Rel;
        if (Target != static_cast<intptr_t>(S.SuperRva)) return "super-mismatch";
        if (ResolveFunctionStartRva(S.SuperRva) != S.SuperRva) return "super-not-entry";
    }
    return nullptr;
}

static void CwLogInstalled(const CwSite& S, MH_STATUS Create, MH_STATUS Enable) {
    MpLog(std::string("[CalloutGuard] install site=") + S.Name + " rva=+" + MpHex(S.Rva)
        + " entry=pdata bytes=match super=" + (S.SuperCallOffset ? ("+" + MpHex(S.SuperRva) + "(decoded)") : std::string("none"))
        + " create=" + MH_StatusToString(Create) + " enable=" + MH_StatusToString(Enable));
}

